const tr341=v=>typeof t==='function'?t(v):v;
const num341=v=>Number(v||0), txt341=v=>String(v??'').trim();
try{Object.assign(KO,{
  'Access Control Center':'접근 권한 관리 센터','Access Overview':'접근 개요','Security Defaults':'보안 기본값','Access Policies':'접근 정책','Access Policy':'접근 정책','Access Audit':'접근 감사','Approval Levels':'승인 레벨','Job Title / Position':'직책 / 직위','System Access':'시스템 접근','Add Another Profile':'프로필 추가','Add Another Group':'권한 그룹 추가','Preview Effective Access':'유효 접근 권한 미리보기','Create User & Assign Access':'사용자 생성 및 접근 권한 배정','Open Security & Access Settings':'보안 및 접근 설정 열기','Permission Group Library':'권한 그룹 라이브러리','Create Permission Group':'권한 그룹 생성','Edit Permission Group':'권한 그룹 수정','Archive Permission Group':'권한 그룹 보관','Create Access Policy':'접근 정책 생성','Edit Access Policy':'접근 정책 수정','Archive Access Policy':'접근 정책 보관','Policy Rules':'정책 규칙','Add Rule':'규칙 추가','Company Wide':'회사 전체','Rule Type':'규칙 유형','Deny Action':'작업 차단','Require Approval Level':'승인 레벨 필요','Require Permission':'권한 필요','Require Permission Group':'권한 그룹 필요','CEO / Owner Only':'CEO / 소유자 전용','Minimum Level':'최소 레벨','Rule Message':'규칙 메시지','Affected Users':'영향받는 사용자','Default Limits':'기본 한도','Access Profiles are created in System Settings and assigned here.':'접근 프로필은 시스템 설정에서 생성하고 여기에서 사용자에게 배정합니다.','Permission Groups bundle multiple related permissions into one reusable add-on.':'권한 그룹은 여러 관련 권한을 하나의 재사용 가능한 추가 권한으로 묶습니다.','Access Policies bundle multiple runtime restriction rules into one policy set.':'접근 정책은 여러 런타임 제한 규칙을 하나의 정책 세트로 묶습니다.','Primary profile is used for legacy display/default context; all assigned profiles remain additive.':'기본 프로필은 기존 표시 및 기본 컨텍스트에 사용되며, 배정된 모든 프로필 권한은 합산됩니다.','Only Finance Verified costs lock normal Edit.':'재무 검증 완료된 비용만 일반 수정을 잠급니다.'
})}catch(_){ }

const moduleLabels341={dashboard:'Dashboard',businesses:'Business Units',sales:'Sales',purchases:'Purchases',inventory:'Inventory',finance:'Finance',accounting:'Accounting',approvals:'Approvals',tasks:'Tasks',performance:'People & Performance',reports:'Reports',documents:'Documents',meetings:'Meetings',restaurant:'MIMI Restaurant',excavator:'Excavator Operations',excavatorSuppliers:'Excavator Suppliers',excavatorBuyers:'Excavator Buyers',notifications:'Notifications',users:'Users & Access',audit:'Audit',payroll:'Employees & Payroll'};
